// Shared illustrations + illustrative stories (NOT real customers).
function band($a,$b,$w=300){return '<svg viewBox="0 0 300 300" width="'.$w.'" aria-hidden="true"><defs><linearGradient id="g'.$a.$w.'" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#'.$a.'"/><stop offset="1" stop-color="#'.$b.'"/></linearGradient></defs><ellipse cx="150" cy="160" rx="112" ry="104" fill="none" stroke="url(#g'.$a.$w.')" stroke-width="34"/><ellipse cx="150" cy="160" rx="112" ry="104" fill="none" stroke="#fff" stroke-opacity=".18" stroke-width="6" transform="translate(-6 -8)"/><rect x="104" y="40" width="92" height="64" rx="14" fill="#fff"/><g fill="#0A1F33"><rect x="114" y="50" width="20" height="20" rx="3"/><rect x="166" y="50" width="20" height="20" rx="3"/><rect x="114" y="74" width="20" height="20" rx="3"/><rect x="142" y="58" width="8" height="8"/><rect x="142" y="76" width="14" height="8"/><rect x="164" y="78" width="10" height="10"/><rect x="178" y="74" width="8" height="18"/></g></svg>';}
function person($skin,$hair,$shirt,$bg='ffffff',$w=190){return '<svg viewBox="0 0 200 200" width="'.$w.'" aria-hidden="true"><circle cx="100" cy="100" r="96" fill="#'.$bg.'"/><path d="M30 190c4-42 36-60 70-60s66 18 70 60z" fill="#'.$shirt.'"/><rect x="88" y="104" width="24" height="30" rx="10" fill="#'.$skin.'"/><circle cx="100" cy="82" r="34" fill="#'.$skin.'"/><path d="M64 80c-2-30 20-46 40-44 22 2 36 20 32 46-6-14-16-22-36-22s-30 8-36 20z" fill="#'.$hair.'"/><circle cx="88" cy="86" r="3" fill="#0A1F33"/><circle cx="112" cy="86" r="3" fill="#0A1F33"/><path d="M90 102q10 8 20 0" stroke="#0A1F33" stroke-width="3" fill="none" stroke-linecap="round"/><ellipse cx="150" cy="168" rx="16" ry="7" fill="none" stroke="#14B8A6" stroke-width="6"/></svg>';}
function stories(){return [
'aisyah-asthma'=>['name'=>'Aisyah','cond'=>'Asthma','quote'=>'A stranger scanned my wrist and knew about my inhaler.','sum'=>'A night-market collapse, and a bystander who knew what to say to the ambulance crew.','c'=>['E0B089','2B1B12','14B8A6','D6F5F0'],'scan'=>['O+','None known','Asthma','Salbutamol inhaler','Sister'],
 'body'=>['I have had asthma since I was nine, and most days it is just part of life. Then one humid Saturday at a night market the air got thick, my chest tightened, and my inhaler was in a bag I had left at a friend\'s stall.','I remember sitting on the kerb unable to finish a sentence. A stranger crouched beside me, noticed the band on my wrist and scanned it with his phone. In a few seconds he could read my conditions, my medication and my sister\'s number.','When the ambulance arrived he told the crew, calmly, that I had asthma and used a salbutamol inhaler. They started treatment in the vehicle without having to ask me a single question I could not answer.','What stays with me is how ordinary the moment was. No app, no password. Just a phone camera and a small square on my wrist.']],
'daniel-allergy'=>['name'=>'Daniel','cond'=>'Penicillin allergy','quote'=>'The ER skipped the one drug that could have hurt me.','sum'=>'After a bike accident, an allergy shown in red at the top of the screen.','c'=>['C68642','111827','2563EB','DCE8FF'],'scan'=>['A-','Penicillin (severe)','None','None','Wife'],
 'body'=>['I ride to work most days. One morning a car clipped my handlebars and I woke up on the pavement with a broken wrist and a head that would not stay clear.','I have a severe penicillin allergy, the kind that closes your throat. In that state I could not have told anyone, and I was drifting in and out.','A passer-by scanned my band while we waited for help. The scan page shows allergies in red, right under the blood type, so it was the first thing the paramedic saw. It was written on the hospital notes before I reached the door.','My wife says she got the call before I was even wheeled in. I got the right antibiotics and she got her answers.']],
'meiling-diabetes'=>['name'=>'Mei Ling','cond'=>'Type 1 diabetes','quote'=>'My sister got the call in minutes, not hours.','sum'=>'A collapse at the gym, and a one-tap call to family while paramedics read the profile.','c'=>['F1C27D','6B3F1D','F59E0B','FFEFD0'],'scan'=>['B+','Sulfa drugs','Type 1 diabetes','Insulin pump','Sister'],
 'body'=>['Living with type 1 diabetes means doing sums all day. That evening at the gym, I got them wrong and my blood sugar dropped fast.','The next thing I knew, staff were around me. Someone had spotted my band, scanned it and seen two things straight away: type 1 diabetes and an insulin pump.','They tapped the big red call button for my sister while the paramedics read my profile. By the time I was talking again, she was already on the way.','Before, my family would find out hours later. Now it is minutes, and everyone in the room knew what they were dealing with.']],
'raj-epilepsy'=>['name'=>'Raj','cond'=>'Epilepsy','quote'=>'People stopped guessing and started helping.','sum'=>'A seizure on a busy train platform, and calm strangers who knew what it was.','c'=>['A9714B','1B1B1B','7C3AED','EADCFF'],'scan'=>['AB+','None known','Epilepsy','Levetiracetam','Mother'],
 'body'=>['Most people have never seen a seizure up close, and many panic. I have been on the receiving end of that panic, and it is frightening for everyone.','On a crowded platform I had a seizure. A woman scanned my band and read it out loud: epilepsy, medication, mother\'s number. Suddenly the crowd had a script.','They cleared space, cushioned my head, timed it and waited. When the paramedics came they were told exactly how long it lasted and what I take.','I went home that day feeling something new: not embarrassed, just looked after.']],
'hana-kids-allergy'=>['name'=>'Hana (mum of Adam, 7)','cond'=>'Child nut allergy','quote'=>'He wears it like a superhero band.','sum'=>'A parent\'s story about sending a child with a severe allergy to school.','c'=>['F5CBA7','3B2314','F0484B','FFE1E1'],'scan'=>['O+','Peanuts, tree nuts (anaphylaxis)','Food allergy','Adrenaline auto-injector','Mother'],
 'body'=>['Every parent of an allergic child knows the knot in the stomach on the first day of school. Adam\'s allergy to nuts is severe, and I cannot be at every lunch table.','We chose a bright kids\' band and told Adam it was his superhero band. His teachers know to scan it if he ever seems unwell, and the page tells them his allergy and that he carries an auto-injector.','He has never needed it, thankfully. But the knot is smaller now. If anything happens, whoever is nearest will know what to do and will be able to reach me in one tap.','We update his profile every term, and the QR never changes, so the band he loves keeps working.']]
];}

// ---- v2: use the owner's uploaded photo when there is one, otherwise the illustration ----
function story_art($slug,$s,$w=150){$i=story_img($slug);return $i?'<img class="ph" src="'.e($i).'" alt="'.e($s['name']).'" loading="lazy">':person($s['c'][0],$s['c'][1],$s['c'][2],'ffffff',$w);}
function bracelet_art($b,$w=170){$u=!empty($b['image'])?img_url('bracelets',$b['image']):null;return $u?'<img class="ph" src="'.e($u).'" alt="'.e($b['name']).'" loading="lazy">':band($b['color1'],$b['color2'],$w);}
